using system.text.regularexpressions;

namespace cow_ai.services;

public enum workspaceagentintent
{
    exploreread,
    searchdebug,
    writecreate,
    editrefactor,
    duplicateauditcleanup,
    buildverify
}

public sealed record agentintentanalysis(
    workspaceagentintent intent,
    bool ismutating,
    bool isdestructive,
    string preferredollamamodel,
    string guidancenote
);

/// <summary>
/// phan tich y dinh nlp (tieng viet + tieng anh) cho cac tac vu tren thu muc workspace.
/// </summary>
public sealed class agentintentclassifier
{
    private static readonly regex duplicatedeleteregex = new(
        @"(trung\s*lap|trung\s*ten|file\s*trung|nhan\s*ban|duplicate|dedupe|clone|don\s*dep|xoa\s*bot|xoa\s*bot|remove\s*duplicate|clean\s*up|redundant)",
        regexoptions.ignorecase | regexoptions.compiled);

    private static readonly regex generaldeleteregex = new(
        @"\b(xoa|xoa|delete|remove|wipe|erase)\b",
        regexoptions.ignorecase | regexoptions.compiled);

    private static readonly regex writecreateregex = new(
        @"(tao\s*(file|tep|thu\s*muc|class|module|ham|service|api|trang)|viet\s*(them|file|tep|code|chuong\s*trinh|ham|test|unit\s*test|readme|tai\s*lieu)|them\s*(file|tep|tinh\s*nang|chuc\s*nang|endpoint|controller|model)|create\s*(file|folder|class|module|test)|write\s*(a\s*)?(new\s*)?(file|script|code|test|doc)|add\s*(new\s*)?(file|feature|endpoint)|generate\s*(file|code))",
        regexoptions.ignorecase | regexoptions.compiled);

    private static readonly regex editrefactorregex = new(
        @"(sua\s*(loi|file|code|bug|lai)|chinh\s*sua|cap\s*nhat|nang\s*cap|toi\s*uu|refactor|tach\s*file|doi\s*ten|rename|fix\s*(bug|error|issue)|update\s*(file|code)|modify|patch|replace)",
        regexoptions.ignorecase | regexoptions.compiled);

    private static readonly regex buildverifyregex = new(
        @"(chay\s*(test|build|lenh|kiem\s*thu|npm|dotnet|python)|kiem\s*tra\s*loi\s*bien\s*dich|dotnet\s+build|dotnet\s+test|npm\s+(test|run)|pytest|compile|verify)",
        regexoptions.ignorecase | regexoptions.compiled);

    private static readonly regex searchdebugregex = new(
        @"(tim\s*(kiem|o\s*dau|cho\s*nao|ham|class|file|loi)|tra\s*cuu|giai\s*thich\s*(luong|ham|logic)|nam\s*o\s*dau|where\s*is|find\s+|search\s+|grep|locate|how\s+does)",
        regexoptions.ignorecase | regexoptions.compiled);

    public agentintentanalysis analyze(string prompt)
    {
        var text = (prompt ?? string.empty).trim();

        if (duplicatedeleteregex.ismatch(text))
        {
            return new agentintentanalysis(
                intent: workspaceagentintent.duplicateauditcleanup,
                ismutating: true,
                isdestructive: text.contains("xoa", stringcomparison.ordinalignorecase)
                            || text.contains("xoa", stringcomparison.ordinalignorecase)
                            || text.contains("delete", stringcomparison.ordinalignorecase)
                            || text.contains("remove", stringcomparison.ordinalignorecase)
                            || text.contains("dedupe", stringcomparison.ordinalignorecase),
                preferredollamamodel: "qwen2.5:7b",
                guidancenote: "bat buoc thuc thi tron ven chuoi hanh dong: (1) goi `find_duplicates` truoc de tim ban trung sha-256 va code clone jscpd; (2) neu co `duplicatepaths` va nguoi dung yeu cau xoa/don, goi ngay tool `safe_delete_to_trash` voi danh sach `paths = duplicatepaths` ngay trong luot chay nay (khong hoi lai bang chu). bao cao chinh xac `keeppath` da giu lai va danh sach tep da chuyen vao `.cowai_trash`.");
        }

        if (writecreateregex.ismatch(text))
        {
            var isdestructive = generaldeleteregex.ismatch(text);
            return new agentintentanalysis(
                intent: workspaceagentintent.writecreate,
                ismutating: true,
                isdestructive: isdestructive,
                preferredollamamodel: "qwen2.5-coder:7b",
                guidancenote: isdestructive
                    ? "thuc hien ngay ca 2 buoc bang tool: (1) goi `safe_delete_to_trash` cho dung cac tep thuc te can xoa; (2) goi `fs_write` tao/ghi noi dung tep moi hoan chinh roi bao cao ngan gon."
                    : "nguoi dung yeu cau tao/viet moi tep hoac ma nguon. dung `fs_write` tao tep thuc te vao dung thu muc va xac nhan lai bang `fs_read`.");

