    private static string ExtractTopicHeadline(string markdown)
    {
        // Ưu tiên dòng in đậm lớn hoặc tiêu đề có nghĩa
        var boldMatch = Regex.Match(markdown, @"\*\*(?:BÁO CÁO|ĐỒ ÁN|TỔNG QUAN|CHỦ ĐỀ)?\s*([^\*\n]{3,60})\*\*", RegexOptions.IgnoreCase);
        if (boldMatch.Success)
        {
            var b = boldMatch.Groups[1].Value.Trim();
            if (!b.StartsWith("Slide", StringComparison.OrdinalIgnoreCase)) return b;
        }

        var hMatch = Regex.Match(markdown, @"^\s*#+\s+(.+)$", RegexOptions.Multiline);
        if (hMatch.Success)
        {
            var h = hMatch.Groups[1].Value.Trim();
            if (!h.StartsWith("Slide", StringComparison.OrdinalIgnoreCase))
                return h.Length > 90 ? h[..90] : h;
        }

        var lines = markdown.Split('\n', StringSplitOptions.RemoveEmptyEntries)
            .Select(l => l.Trim().Trim('#', '*', ' ', '-'))
            .Where(l => l.Length > 3 && !l.StartsWith("Slide", StringComparison.OrdinalIgnoreCase) && !l.StartsWith("---"))
            .ToList();

        var firstValid = lines.FirstOrDefault() ?? "Bài giảng AI Studio";
        return firstValid.Length > 80 ? firstValid[..80] : firstValid;
    }

    private static string DistillSourceForScript(string sourceMd, string topicTitle, int maxChars = 5000)
    {
        if (string.IsNullOrWhiteSpace(sourceMd) || sourceMd.Length <= maxChars) return sourceMd;

        var lines = sourceMd.Replace("\r\n", "\n").Split('\n');
        var sb = new StringBuilder();
        sb.AppendLine($"# {topicTitle}\n");

        int currentLength = sb.Length;
        foreach (var rawLine in lines)
        {
            var line = rawLine.Trim();
            if (string.IsNullOrWhiteSpace(line)) continue;
            if (line.StartsWith("---") || line.StartsWith("title:") || line.StartsWith("mimeType:") || line.StartsWith("generated:") || line.StartsWith("images:"))
                continue;

            bool isHeading = line.StartsWith('#');
            bool isKeyPoint = line.StartsWith("-") || line.StartsWith("*") || line.StartsWith("•") || Regex.IsMatch(line, @"^\d+\.");
            bool isHighlighted = line.StartsWith("**") || (line.Contains(':') && line.Length < 120);

            if (isHeading || isKeyPoint || isHighlighted)
            {
                if (currentLength + line.Length + 1 > maxChars) break;
                sb.AppendLine(line);
