    private static string distillsourceforscript(string sourcemd, string topictitle, int maxchars = 5000)
    {
        if (string.isnullorwhitespace(sourcemd) || sourcemd.length <= maxchars) return sourcemd;

        var lines = sourcemd.replace("\r\n", "\n").split('\n');
        var sb = new stringbuilder();
        sb.appendline($"# {topictitle}\n");

        int currentlength = sb.length;
        foreach (var rawline in lines)
        {
            var line = rawline.trim();
            if (string.isnullorwhitespace(line)) continue;
            if (line.startswith("---") || line.startswith("title:") || line.startswith("mimetype:") || line.startswith("generated:") || line.startswith("images:"))
                continue;

            bool isheading = line.startswith('#');
            bool iskeypoint = line.startswith("-") || line.startswith("*") || line.startswith("•") || regex.ismatch(line, @"^\d+\.");
            bool ishighlighted = line.startswith("**") || (line.contains(':') && line.length < 120);

            if (isheading || iskeypoint || ishighlighted)
            {
                if (currentlength + line.length + 1 > maxchars) break;
                sb.appendline(line);
                currentlength += line.length + 1;
            }
        }

        if (sb.length < 300)
        {
            return sourcemd[..math.min(maxchars, sourcemd.length)];
        }

        return sb.tostring().trim();
    }

