            {
                var cleanrel = rel.replace('/', path.directoryseparatorchar).trimstart(path.directoryseparatorchar);
                var fullfile = path.combine(cand, cleanrel);
                if (file.exists(fullfile))
                {
                    score += 3;
                    try
                    {
                        if (size >= 0 && new fileinfo(fullfile).length == size)
                        {
                            score += 2;
                        }
                    }
                    catch { }
                }
            }

            if (score > bestscore)
            {
                bestscore = score;
                bestcandidate = cand;
            }
        }

        if (bestcandidate != null && bestscore >= 3)
        {
            _logger.loginformation("tryresolvereallocalfolder da anh xa thu muc '{folder}' -> duong dan that '{realpath}' (score={score})",
                targetname, bestcandidate, bestscore);
            return bestcandidate;
        }

        // truong hop chi co 1 thu muc duy nhat trung ten tren may (vi du thu muc nguoi dung vua tao/xoa file)
        if (candidates.count == 1)
        {
            return candidates[0];
        }

        return null;
    }
}

