    /// </summary>
    public string getimageurl(string prompt, int width = 1024, int height = 1024, string model = "flux")
    {
        var cleanprompt = prompt?.trim() ?? string.empty;
        var encodedprompt = uri.escapedatastring(cleanprompt);
