  color: var(--cow-text);
  font-weight: 700;
  letter-spacing: -0.025em;
}

.brand-title-accent {
  color: var(--cow-accent);
}

/* Desktop Navigation Menu (Semantic & Chuẩn SEO) */
.navbar-nav {
  display: flex;
  align-items: center;
}

.nav-menu-list {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  list-style: none;
  margin: 0;
  padding: 0;
}

.nav-menu-item {
  display: inline-flex;
  align-items: center;
}

.nav-link {
  color: var(--cow-text-muted);
  text-decoration: none;
  font-size: 0.9rem;
  font-weight: 500;
  padding: 0.45rem 0.75rem;
  border-radius: var(--radius-sm);
  transition: color var(--transition-fast), background-color var(--transition-fast);
  position: relative;
}

.nav-link:hover,
.nav-link:focus-visible {
  color: var(--cow-text);
  background: var(--cow-glass-hover);
}

.nav-link.active {
  color: var(--cow-text);
  background: var(--cow-glass-hover);
  font-weight: 600;
}

/* Navbar Actions (Theme Switcher & Mobile Menu Toggle) */
.navbar-actions {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  flex-shrink: 0;
}

/* Mobile Nav Toggle Button */
.mobile-nav-toggle {
  display: none;
  background: transparent;
  border: 1px solid var(--cow-glass-border, rgba(255, 255, 255, 0.1));
  color: var(--cow-text-muted, #94a3b8);
  width: 2.25rem;
