/* ==========================================================================
   COW.AI - Pages CSS (Custom styles for specific views)
   ========================================================================== */



/* ==========================================================================
   1. Home / Duck.ai-Style Interactive Chat Viewport (R1 & R2)
   ========================================================================== */

.chat-app-viewport {
  width: 100%;
  height: 100vh;
  height: 100dvh;
  max-height: 100vh;
  max-height: 100dvh;
  display: flex;
  flex-direction: column;
  position: relative;
  box-sizing: border-box;
  overflow: hidden;
  z-index: 10;
}

/* 1.1 Initial Centered Mode (Trạng thái khởi tạo) */
.chat-app-viewport:not(.bottom-mode) {
  min-height: 100vh;
  min-height: 100dvh;
  height: auto;
  max-height: none;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 1.5rem 1.5rem 2.5rem;
  box-sizing: border-box;
}

/* 1.2 Bottom-Docked Mode (Trạng thái hội thoại hoạt động) */
.chat-app-viewport.bottom-mode {
  height: 100vh;
  height: 100dvh;
  max-height: 100vh;
  max-height: 100dvh;
  justify-content: flex-start;
  align-items: stretch;
  overflow: hidden;
  padding: 0;
}

/* Hide footer and outer scroll when chat is active */
body.chat-active .footer-glass {
  display: none !important;
}

body.chat-active {
  overflow: hidden;
}

body.chat-active .main-content {
  overflow: hidden;
  height: 100vh;
  height: 100dvh;
  padding-bottom: 0;
}

/* 1.3 Duck.ai-Style Logo & Welcome Header (Tham chiếu Hình 2) */
.chat-hero-header {
  text-align: center;
  width: 100%;
  max-width: 52rem;
  margin: 0 auto 1.5rem;
  opacity: 1;
  transform: translateY(0);
  transition: max-height 0.45s cubic-bezier(0.25, 1, 0.5, 1),
              opacity 0.3s ease,
              transform 0.35s ease,
              margin 0.45s cubic-bezier(0.25, 1, 0.5, 1);

