  margin: var(--space-4) auto var(--space-5);
  padding: 0 var(--space-3);
}

.ai-app-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-5); /* gap: 32px - Mục 5.4 & Prompt 2 */
