/* ==========================================================================
   COW.AI - Global Design System & Site Core (UI/UX Pro Max Engine)
   Standard: 60-30-10 Color Architecture, Modular Spacing & Zero AI-Slop
   ========================================================================== */

:root {
  /* Obsidian & Cobalt Design System (60-30-10, WCAG 2.2 AA, Zero AI-Slop) */
  --cow-bg: #09090b;
  --cow-bg-secondary: #121316;
  --cow-surface-card: #141519;
  --cow-surface-elevated: #1b1c22;
  --cow-border: #27272a;
  --cow-border-strong: #3f3f46;
  --cow-text: #f4f4f5;
  --cow-text-muted: #a1a1aa;
  --cow-accent: #38bdf8;
  --cow-accent-hover: #7dd3fc;
  --cow-accent-soft: rgba(56, 189, 248, 0.12);
  --cow-accent-green: #22c55e;
  --cow-cta-bg: #f4f4f5;
  --cow-cta-hover: #e4e4e7;
  --cow-cta-text: #09090b;
  --cow-badge-bg: #18181b;
  --cow-badge-text: #e4e4e7;
  --cow-badge-border: #27272a;
  --cow-vignette-center: #0e1118;
  --cow-silk-primary: rgba(56, 189, 248, 0.11);
  --cow-silk-secondary: rgba(99, 102, 241, 0.06);
  --cow-silk-ambient: rgba(14, 165, 233, 0.045);
  --cow-cursor-glow: rgba(56, 189, 248, 0.065);
  --cow-card-highlight: inset 0 1px 0 rgba(255, 255, 255, 0.06), 0 8px 24px rgba(0, 0, 0, 0.28);
  --cow-grain-opacity: 0.022;

  --cow-glass-bg: rgba(18, 19, 22, 0.88);
  --cow-glass-hover: rgba(255, 255, 255, 0.06);
  --cow-glass-border: rgba(255, 255, 255, 0.08);
  --cow-input-bg: #141519;
  --cow-msg-user-bg: #1e293b;
  --cow-msg-ai-bg: #141519;

  --code-editor-bg: #0f1014;
  --code-editor-header: #16171d;
  --code-editor-border: #27272a;
  --code-editor-text: #f4f4f5;

  /* Modular Spacing Scale (8-Point Rhythm) */
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 16px;
  --space-4: 24px;
  --space-5: 32px;
  --space-6: 48px;

  /* Standard Border Radii (Craft Floor: 4px to 16px) */
  --radius-xs: 4px;
  --radius-sm: 6px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;

  /* Typography Stacks (Plus Jakarta Sans Vietnamese + JetBrains Mono Code) */
  --font-sans: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --font-mono: 'JetBrains Mono', ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;

  /* Responsive Micro-Interaction Timings (150-250ms) */
  --transition-fast: 150ms cubic-bezier(0.22, 1, 0.36, 1);
  --transition-base: 200ms cubic-bezier(0.22, 1, 0.36, 1);
  --transition-slow: 300ms cubic-bezier(0.22, 1, 0.36, 1);
}

/* Light Mode Overrides (Clean Paper Surface - High Contrast WCAG 2.2 AA) */
html.light,
body.light,
html.light body,
:root.light {
  --cow-bg: #f8fafc;
  --cow-bg-secondary: #f1f5f9;
  --cow-surface-card: #ffffff;
  --cow-surface-elevated: #f8fafc;
  --cow-border: #e4e4e7;

