  --studio-card-border: #272727;
  --studio-card-hover-bg: #1f1f1f;
  --studio-card-hover-border: #313131;
  --studio-active-border: #ffffff;
  --studio-modal-bg: #181818;
  --studio-modal-border: #272727;
}

