        normalized = System.Text.RegularExpressions.Regex.Replace(normalized, @"@([a-zA-Z0-9_\-]+)", "$1");
        normalized = System.Text.RegularExpressions.Regex.Replace(normalized, @"([a-zA-Z0-9_])\/([a-zA-Z0-9_])", "$1 trên $2");

