            cleaned = System.Text.RegularExpressions.Regex.Replace(cleaned, @"\s*```\s*$", "", System.Text.RegularExpressions.RegexOptions.IgnoreCase);
            cleaned = cleaned.Replace("<tool_call>", "").Replace("</tool_call>", "").Trim();

            try
