    private string StoreEphemeralImage(byte[] bytes, string contentType)
    {
        var id = Guid.NewGuid().ToString("N");
        _imageCache[id] = new CachedImageEntry(bytes, contentType, DateTimeOffset.UtcNow);
        _cacheOrder.Enqueue(id);

