            "120b-cloud" or "120b" or "gpt-oss-120b" => "gpt-oss:120b",
            "mistral-nemo" or "neu" or "nemo" => "mistral-nemo:latest",
            "phi4-cloud" or "phi4" or "phi-4" => "phi4:latest",
            _ => key
        };
    }

