    public async Task<(bool Success, string? Error, string? AudioUrl, double Duration)> GenerateSceneAudioAsync(int sceneId)
    {
        var scene = await _db.Scenes.Include(s => s.Project).FirstOrDefaultAsync(s => s.Id == sceneId);
