        }
        catch (OperationCanceledException)
        {
            try { proc.Kill(entireProcessTree: true); } catch { }
            return (-1, "Tiến trình hết thời gian chờ.");
        }

        var stdErr = await stdErrTask;
        _ = await stdOutTask;
        return (proc.ExitCode, stdErr);
    }

