function buildTrigrams(text) {
  const clean = foldVi(text).replace(/\s+/g, ' ').trim();
  const counts = new Map();
  if (clean.length < 3) return counts;
  for (let i = 0; i <= clean.length - 3 && i < 6000; i++) {
    const g = clean.slice(i, i + 3);
