/* Menu Popover (Mặc định xổ xuống dưới trong Centered Mode để không che ô nhập và logo) */
.model-menu {
  position: absolute;
  top: calc(100% + 8px);
  bottom: auto;
  left: 0;
  width: 240px;
  max-width: calc(100vw - 32px);
  max-height: 320px;
  overflow-y: auto;
  overflow-x: hidden;
  -webkit-overflow-scrolling: touch;
  background-color: var(--cow-glass-bg);
  backdrop-filter: blur(24px);
  -webkit-backdrop-filter: blur(24px);
  border: 1px solid var(--cow-glass-border);
  border-radius: 6px;
  box-shadow: 0 16px 36px rgba(0, 0, 0, 0.45);
  padding: 6px;
  z-index: 1000;
  opacity: 0;
  visibility: hidden;
  transform: translateY(-8px) scale(0.98);
  transition: opacity 0.2s cubic-bezier(0.16, 1, 0.3, 1),
              transform 0.2s cubic-bezier(0.16, 1, 0.3, 1),
              visibility 0.2s cubic-bezier(0.16, 1, 0.3, 1);
  display: flex;
  flex-direction: column;
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, 0.2) transparent;
}

/* Thanh cuộn mỏng (6px) chống tràn màn hình */
