  }

  function toggleListening() {
    if (isListening) {
      stopListening();
    } else {
      startListening();
    }
  }

  global.CowAiVoiceInput = {
    init: initVoiceInput,
    start: startListening,
    stop: stopListening,
    toggle: toggleListening,
    isSupported: isSpeechSupported
  };

